def floaters() -> str:
    rnd = random.Random(7)
    glyphs = ["♪", "♥", "✦", "♫", "☁", "✿","👾","🎃"]
    out = []
    for _ in range(22):
        out.append(
            f'<span style="left:{rnd.randint(2, 96)}%;font-size:{rnd.randint(16, 38)}px;'
            f'animation-duration:{rnd.randint(14, 28)}s;animation-delay:-{rnd.randint(0, 28)}s">'
            f"{rnd.choice(glyphs)}</span>"
        )
    return '<div class="bg"><div class="blob b1"></div><div class="blob b2"></div><div class="blob b3"></div>' + "".join(out) + "</div>"


