# ------------------------------------------------------------------ voice agent


@st.cache_resource
def get_pipeline(api_key: str) -> dict:
    """One pipeline plus ONE long-lived event loop on a background thread.
    asyncio.run() would create and close a loop per question, which breaks the
    cached OpenAI client ("Event loop is closed")."""
    agent = Agent(
        name="Travel Advisor",
        instructions=(
            "You are a friendly travel advisor. "
            "Keep spoken answers short, natural, and easy to follow. "
            "Answer ONLY what the user asked, as briefly as possible: usually one sentence, never more than two. "
            "No greetings, no intro, no extra tips, no suggestions, no follow-up questions, "
            "no summary or closing line. If they ask a yes/no or one-fact question, give just that. "
            "Give more detail only if the user explicitly asks for it. "
            "ALWAYS reply in the same language the user asked in (for example Urdu, Hindi, "
            "Arabic, Punjabi, English or any other), written in that language's normal script. "
            "Never switch to English unless the user spoke English."
        ),
        model="gpt-5.4-mini",
    )
    pipeline = VoicePipeline(
        workflow=SingleAgentVoiceWorkflow(agent),
        config=VoicePipelineConfig(
            model_provider=OpenAIVoiceModelProvider(api_key=api_key),
            tts_settings=TTSModelSettings(
                voice="nova",
                speed=1.0,
                instructions=(
                    "Speak like a warm, cheerful young woman chatting with a friend. "
                    "Gentle smile in the voice, relaxed natural pace, clear pronunciation. "
                    "Speak in the language of the text with a native, natural accent."
                ),
            ),
            trace_include_sensitive_audio_data=False,
        ),
    )
    loop = asyncio.new_event_loop()
    threading.Thread(target=loop.run_forever, daemon=True).start()
    return {"pipeline": pipeline, "loop": loop}


def wav_to_pcm(raw: bytes) -> np.ndarray:
    """Decode the browser's WAV recording to mono int16 at 24 kHz."""
    with wave.open(io.BytesIO(raw)) as w:
        rate, ch = w.getframerate(), w.getnchannels()
        data = np.frombuffer(w.readframes(w.getnframes()), dtype=np.int16)
    if ch > 1:
        data = data.reshape(-1, ch).mean(axis=1)
    if rate != SAMPLE_RATE:
        n = int(len(data) * SAMPLE_RATE / rate)
        data = np.interp(np.linspace(0, len(data) - 1, n), np.arange(len(data)), data)
    return data.astype(np.int16)


async def _ask(pipeline: VoicePipeline, pcm: np.ndarray):
    result = await pipeline.run(AudioInput(buffer=pcm))
    chunks = []
    async for event in result.stream():
        if event.type == "voice_stream_event_audio":
            chunks.append(event.data)
    audio = np.concatenate(chunks) if chunks else np.zeros(1, dtype=np.int16)
    buf = io.BytesIO()
    with wave.open(buf, "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(SAMPLE_RATE)
        w.writeframes(audio.astype(np.int16).tobytes())
    return buf.getvalue(), result.total_output_text


def ask(api_key: str, pcm: np.ndarray):
    rt = get_pipeline(api_key)
    return asyncio.run_coroutine_threadsafe(_ask(rt["pipeline"], pcm), rt["loop"]).result(timeout=120)


def check_key(key: str) -> str | None:
    """Return None if the key works, otherwise a plain-language problem."""
    if not key.startswith("sk-") or len(key) < 20:
        return "That does not look like an OpenAI key. It starts with sk- and is much longer."
    try:
        from openai import OpenAI

        OpenAI(api_key=key).models.list()
    except Exception as exc:
        name = type(exc).__name__
        if "Authentication" in name:
            return "OpenAI rejected this key. Check it for typos or create a new one."
        if "Connection" in name:
            return "Could not reach OpenAI. Check your internet connection and try again."
        return f"Could not verify the key ({name})."
    return None


