def avatar_html(state: str, title: str | None = None, sub: str | None = None) -> str:
    head, tail = STATES[state]
    img = f'<img src="{AV}" alt="voice agent wearing headphones">' if AV else '<div class="ph"></div>'
    bars = "".join(f'<i style="--i:{i}"></i>' for i in range(23))
    return (
        f'<div class="av {state}"><div class="ring r1"></div><div class="ring r2"></div>{img}'
        f'<div class="dots"><i></i><i></i><i></i></div></div>'
        f'<div class="eq {state}">{bars}</div>'
        f'<div class="status">{title or head}<small>{sub or tail}</small></div>'
    )


ss = st.session_state
ss.setdefault("api_key", None)
ss.setdefault("history", [])
ss.setdefault("mic", 0)
ss.setdefault("last_key", None)
ss.setdefault("autoplay", False)

# ------------------------------------------------------------------ step 1: ask for the API key

if not ss["api_key"]:
    st.markdown('<h1 class="t">voice agent</h1><p class="s">Your voice travel advisor</p>', unsafe_allow_html=True)
    st.markdown(avatar_html("ready", "Hi, I'm voice agent", "Enter your OpenAI API key to start talking"), unsafe_allow_html=True)
    with st.form("login", border=True):
        key = st.text_input("OpenAI API key", type="password", placeholder="sk-...")
        go = st.form_submit_button("Unlock voice agent", use_container_width=True)
    if go:
        key = key.strip()
        with st.spinner("Checking your key..."):
            problem = check_key(key)
        if problem:
            st.error(problem)
        else:
            ss["api_key"] = key
            st.rerun()
    st.markdown(
        '<p class="note">Your key stays in this browser session only. It is never saved to disk.</p>',
        unsafe_allow_html=True,
    )
    st.stop()

# ------------------------------------------------------------------ step 2: the voice agent

set_default_openai_key(ss["api_key"], use_for_tracing=False)

left, right = st.columns([3, 1.4])
with left:
    st.markdown('<h1 class="t" style="text-align:left">Wayfinder</h1>', unsafe_allow_html=True)
with right:
    if st.button("Change key", use_container_width=True):
        get_pipeline.clear()
        for k in ("api_key", "history", "last_key"):
            ss[k] = None if k != "history" else []
        ss["mic"] += 1
        st.rerun()

stage = st.empty()
stage.markdown(avatar_html("speaking" if ss["autoplay"] else "ready"), unsafe_allow_html=True)

audio = st.audio_input("Ask the travel advisor", key=f"mic{ss['mic']}", label_visibility="collapsed")
st.markdown('<p class="hint">Tap the mic, ask your question, tap again to send</p>', unsafe_allow_html=True)

if audio is not None:
    raw = audio.getvalue()
    key = hashlib.md5(raw).hexdigest()
    if ss["last_key"] != key:
        ss["last_key"] = key
        stage.markdown(avatar_html("thinking"), unsafe_allow_html=True)
        try:
            wav, text = ask(ss["api_key"], wav_to_pcm(raw))
        except Exception as exc:
            stage.markdown(avatar_html("ready"), unsafe_allow_html=True)
            st.error(f"The advisor could not answer: {exc}. If your key was revoked, use Change key.")
        else:
            ss["history"].append({"wav": wav, "text": text})
            ss["autoplay"] = True
            stage.markdown(avatar_html("speaking"), unsafe_allow_html=True)

if not ss["history"]:
    st.markdown(
        '<div class="chips"><span>Best time to visit Japan?</span><span>3 days in Lisbon</span>'
        "<span>Cheap beach trip in Asia</span></div>",
        unsafe_allow_html=True,
    )

mini = f'<img class="mini" src="{AV}" alt="">' if AV else ""
for i, turn in enumerate(ss["history"]):
    st.markdown('<div class="turn you"><div class="bub"><p>Voice question</p></div></div>', unsafe_allow_html=True)
    st.markdown(
        f'<div class="turn">{mini}<div class="bub"><p dir="auto">{html.escape(turn["text"])}</p></div></div>',
        unsafe_allow_html=True,
    )
    st.audio(turn["wav"], format="audio/wav", autoplay=(i == len(ss["history"]) - 1) and ss["autoplay"])

ss["autoplay"] = False
